#!/usr/bin/env node

/**
 * Post-install patch script for @churchapps/helpers
 *
 * Fixes a bug in the published @churchapps/helpers EventHelper.getFullRRule:
 * it builds the RRule via `RRule.fromString(rule)` and then mutates
 * `rrule.options.dtstart` afterward. rrule.js freezes dtstart-derived
 * internal state at construction time, so that mutation is a no-op.
 * For bare rule strings with no embedded DTSTART (e.g. "FREQ=MONTHLY",
 * as generated by the event modals), RRule.fromString defaults dtstart
 * to "now", causing recurring events to expand using today's
 * day-of-month/weekday instead of the event's actual start date.
 *
 * This patches dist/EventHelper.js to build the options via
 * RRule.parseString first, set dtstart on the options object, then
 * construct `new RRule(options)` - matching the fix already present in
 * the upstream ChurchApps/Packages source (not yet published to npm).
 */

const fs = require('fs');
const path = require('path');

const EVENT_HELPER_PATH = path.join(__dirname, '../node_modules/@churchapps/helpers/dist/EventHelper.js');

try {
  if (!fs.existsSync(EVENT_HELPER_PATH)) {
    process.exit(0);
  }

  let content = fs.readFileSync(EVENT_HELPER_PATH, 'utf8');

  const originalBlock = `const rrule = RR.fromString(event.recurrenceRule);
        rrule.options.dtstart = new Date(event.start);
        return rrule;`;

  const patchedBlock = `const options = RR.parseString(event.recurrenceRule) || {};
        options.dtstart = new Date(event.start);
        const rrule = new RR(options);
        return rrule;`;

  if (content.includes(patchedBlock)) {
    process.exit(0);
  }

  if (content.includes(originalBlock)) {
    content = content.replace(originalBlock, patchedBlock);
    fs.writeFileSync(EVENT_HELPER_PATH, content, 'utf8');
  }

} catch (error) {
  // Do not fail the install if patching fails
  process.exit(0);
}
